INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @post_id,'_rank_math_description','امروزه با توجه به کمبود منابع آبی، آبیاری قطره‌ای به عنوان راهکار اصلی افزایش بهره‌وری شناخته شده است. در این مقاله، نوار تیپ با فاصله قطره‌چکان ۲۰ سانتی‌متر را از نظر ساختار، انتخاب دبی، اصول نصب و مراقبت‌های اساسی بررسی می‌کنیم. هدف ما کمک به کشاورزان برای جلوگیری از گرفتگی، کاهش تلفات و افزایش عمر سیستم است. بدون ادعاهای محلی از اقلیم خاص، بر اصول عمومی فنی تمرکز داریم تا شما بتوانید تصمیمی دقیق برای مزرعه خود بگیرید.' WHERE @created_post=1 AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@post_id AND meta_key='_rank_math_description');
